def main():
    """Основная функция для обучения моделей на сервере"""
    
    # Пути к данным (текущая директория)
    BASE_DATA_DIR = "."
    
    SEG_TRAIN = f"{BASE_DATA_DIR}/db_segmentation_train.json"
    SEG_VAL = f"{BASE_DATA_DIR}/db_segmentation_val.json"
    NER_TRAIN = f"{BASE_DATA_DIR}/db_ner_train.json"
    NER_VAL = f"{BASE_DATA_DIR}/db_ner_val.json"
    
    print("🚀 Начало обучения моделей...")
    print(f"Сегментация: {SEG_TRAIN}, {SEG_VAL}")
    print(f"NER: {NER_TRAIN}, {NER_VAL}")
    
    try:
        # Обучаем сегментацию
        print("\n📊 Обучаем модель сегментации...")
        segmenter = SceneSegmenter(unfreeze_last_n=0)
        trainer_seg = segmenter.train_segmentation_model(
            train_json_path=SEG_TRAIN,
            val_json_path=SEG_VAL,
            epochs=6,
            batch_size=8,
            lr=2e-5,
            weight_decay=0.01,
            patience=4
        )
        
        # Обучаем NER
        print("\n🏷️ Обучаем NER модель...")
        ner = SceneNER(unfreeze_last_n=0)
        trainer_ner = ner.train_ner_model(
            train_json_path=NER_TRAIN,
            val_json_path=NER_VAL,
            epochs=8,
            batch_size=4,
            lr=3e-5,
            warmup_steps=0,
            weight_decay=0.01,
            patience=5
        )
        
        print("✅ Обучение завершено успешно!")
        print(f"Модели сохранены в: {SEGMENTATION_MODEL_PATH}, {NER_MODEL_PATH}")
        
    except Exception as e:
        print(f"❌ Ошибка при обучении: {e}")
        import traceback
        traceback.print_exc()

if __name__ == "__main__":
    main()